#!/usr/bin/env python3
"""Original SH7604 ICR/SCU/SMPC/VDP2 guest, MIT: adjacent LICENSE.

H §5.3.8/table5.4, ST-169 table1.5, ST-058 §2.5/tables2.3–2.4.
No SDK, firmware, external assembler, expected-output capture or emulator core.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_scu import assembler, store

HERE = Path(__file__).resolve().parent
# Source-authored signed quotient/remainder vectors; P §6.19 example4.
DIVISIONS = [(100,7,14,2),(-100,7,-14,-2),(100,-7,-14,2),(-100,-7,14,-2),
             (-2147483648,1,-2147483648,0),(-2147483648,3,-715827882,-2),
             (2147483647,-3,-715827882,1),(0,-2147483648,0,0),
             (-2147483648,-2147483648,1,0),(1,-2147483648,0,1),
             (-1,-2147483648,0,-1),(2147483647,2147483647,1,0),
             (-2147483648,2147483647,-1,-1)]


def program():
    s = 'load 0x06009100,r8\n'
    for dividend, divisor, _, _ in DIVISIONS:
        s += f'load {dividend & 0xffffffff:#x},r2\nload {divisor & 0xffffffff:#x},r0\n'
        s += 'mov r2,r4\nmov r2,r3\nrotcl r3\nsubc r1,r1\nxor r3,r3\nsubc r3,r2\ndiv0s r0,r1\n'
        s += 'rotcl r2\ndiv1 r0,r1\n'*32
        s += 'rotcl r2\naddc r3,r2\nmov.l r2,@r8\nadd #4,r8\nmul.l r0,r2\nsts macl,r5\nsub r5,r4\nmov.l r4,@r8\nadd #4,r8\n'
    s += 'load 0xfffffee0,r1\nmov.w @r1,r0\nload 0x06009000,r8\nmov.l r0,@r8\n'
    s += store(0x06004000, 0x12345678) + store(0x25FE00A0, 0xB7FF)
    s += 'mov #0,r0\nldc r0,sr\nnop\n'
    for stage in range(2):
        if stage:
            s += 'load 0xfffffee0,r1\nmov #1,r0\nmov.w r0,@r1\n'
        for offset, value in [(0,0x06004000),(4,0x06005000+stage*4),(8,4),(12,0x102),(20,7),(16,0x101)]:
            s += store(0x25FE0000+offset,value)
        s += f'load {0x06009004+stage*4:#x},r8\nwait{stage}:\nmov.l @r8,r0\ntst #255,r0\nbt wait{stage}\n'
    # Enable the PAD IRQ, both EXLE inputs and external counter latching.
    s += store(0x25FE00A0, 0xBEFF)
    for offset, value in [(0x79,0),(0x7B,0),(0x7D,3),(0x7F,3)]:
        s += f'load {0x100000+offset:#x},r1\nmov #{value},r0\nmov.b r0,@r1\n'
    s += 'load 0x05f80002,r1\nload 0x200,r0\nmov.w r0,@r1\n'
    s += store(0x0600900C,0x600D)
    s += 'wait_input:\nsleep\nbra wait_input\nnop\n'
    return s


def build():
    rom = bytearray(524288)
    struct.pack_into('>II', rom, 0, 0x200, 0x06100000)
    sections = {0x200: program()}
    # Scratch R12–R14 belong to interrupt handlers; main uses R0/R1/R8.
    for vector, at, result, value in [(66,0x3000,0x06009004,0x42),(0x4B,0x3100,0x06009008,0x4B)]:
        struct.pack_into('>I',rom,vector*4,at)
        sections[at] = f'load {result:#x},r12\nmov #{value},r13\nmov.l r13,@r12\nrte\nnop\n'
    struct.pack_into('>I',rom,0x48*4,0x3200)
    sections[0x3200] = '''load 0x06009010,r12
mov.l @r12,r13
add #1,r13
mov.l r13,@r12
load 0x05f80008,r12
mov.l @r12,r13
load 0x06009014,r12
mov.l r13,@r12
load 0x05f80004,r12
mov.w @r12,r13
load 0x06009018,r14
mov.l r13,@r14
mov.w @r12,r13
add #4,r14
mov.l r13,@r14
rte
nop
'''
    end = 0
    for at, source in sorted(sections.items()):
        code = assembler.assemble(source,base=at)
        assert at >= end
        end = at+len(code)
        rom[at:end] = code
    text = ['# Original interrupt-control and raster-latch guest. MIT: adjacent LICENSE.',
            '# Generated by build_intc.py; all DMA, IRQ and latch results are guest-written.']
    for at in range(0,len(rom),16):
        chunk = rom[at:at+16]
        if any(chunk): text.append(f'{at:04X} '+' '.join(f'{w:04X}' for w in struct.unpack('>8H',chunk)))
    return '\n'.join(text)+'\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    p=argparse.ArgumentParser()
    p.add_argument('--check',action='store_true')
    args=p.parse_args()
    text,digest=build()
    path=HERE/'intc.hex'
    expectations = ''.join(f'{n} / {d}\t{q & 0xffffffff:08X}\t{r & 0xffffffff:08X}\n' for n,d,q,r in DIVISIONS)
    if args.check:
        assert path.read_text()==text,'Rebuild intc.hex'
        assert (HERE/'signed-divisions.tsv').read_text()==expectations,'Rebuild signed-divisions.tsv'
    else:
        path.write_text(text)
        (HERE/'signed-divisions.tsv').write_text(expectations)
    print(f'{"Verified" if args.check else "Built"} intc.hex; expanded ROM SHA-256 {digest}')
